import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    t = int(next(it))

    # read first grid
    first_grid = []
    for _ in range(n):
        first_grid.append(next(it))

    # read second grid
    second_grid = []
    for _ in range(n):
        second_grid.append(next(it))

    # arrays
    N = 10  # maximum n from original arrays (10x10)
    plant = [[[0] * (t+1) for _ in range(n)] for _ in range(n)]
    source_cap = [[0]*n for _ in range(n)]
    sink_cap = [[0]*n for _ in range(n)]
    source_num = [[-1]*n for _ in range(n)]
    sink_num = [[-1]*n for _ in range(n)]

    # directions
    dr = [0, 0, -1, 1]
    dc = [-1, 1, 0, 0]

    # helper
    def is_valid(r, c):
        return 0 <= r < n and 0 <= c < n

    # process first grid
    for i in range(n):
        for j in range(n):
            ch = first_grid[i][j]
            if ch == 'Y' or ch == 'Z':
                plant[i][j][0] = ord(ch) - ord('X')  # Y->1, Z->2
                source_cap[i][j] = 0
            else:
                plant[i][j][0] = 0
                source_cap[i][j] = int(ch)

    # process second grid (overwrites plant[0])
    for i in range(n):
        for j in range(n):
            ch = second_grid[i][j]
            if ch == 'Y' or ch == 'Z':
                plant[i][j][0] = ord(ch) - ord('X')
                sink_cap[i][j] = 0
            else:
                plant[i][j][0] = 0
                sink_cap[i][j] = int(ch)

    # simulate plant spreading
    for curr_time in range(1, t+1):
        for i in range(n):
            for j in range(n):
                plant[i][j][curr_time] = plant[i][j][curr_time-1]
        for i in range(n):
            for j in range(n):
                if plant[i][j][curr_time-1] == 2:  # Z spreads
                    for k in range(4):
                        ni = i + dr[k]
                        nj = j + dc[k]
                        if is_valid(ni, nj) and plant[ni][nj][curr_time-1] == 0:
                            plant[ni][nj][curr_time] = 2

    # assign node numbers
    counter = 1
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] != 0:
                source_num[i][j] = counter
                counter += 1
    for i in range(n):
        for j in range(n):
            if sink_cap[i][j] != 0:
                sink_num[i][j] = counter
                counter += 1

    # flow adjacency matrix (max size 200)
    max_nodes = 200
    flo = [[0]*max_nodes for _ in range(max_nodes)]

    # BFS to find possible source-sink connections
    q = deque()
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] == 0:
                continue
            # new BFS from this source
            q.clear()
            q.append((0, i, j))  # (time, r, c)
            vis = [[False]*n for _ in range(n)]
            vis[i][j] = True
            src = source_num[i][j]
            while q:
                curr_time, r, c = q.popleft()
                if sink_cap[r][c] != 0:
                    flo[src][sink_num[r][c]] = 10000
                if curr_time == t:
                    continue
                if plant[r][c][curr_time] != 0:  # if cell has plant, cannot move from here
                    continue
                for k in range(4):
                    nr = r + dr[k]
                    nc = c + dc[k]
                    if is_valid(nr, nc) and plant[nr][nc][curr_time] == 0 and not vis[nr][nc]:
                        q.append((curr_time+1, nr, nc))
                        vis[nr][nc] = True

    # edges from super source (0) to source nodes
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] != 0:
                flo[0][source_num[i][j]] = source_cap[i][j]

    # edges from sink nodes to super sink (counter)
    for i in range(n):
        for j in range(n):
            if sink_cap[i][j] != 0:
                flo[sink_num[i][j]][counter] = sink_cap[i][j]

    # max flow using DFS (stack)
    def get_path():
        parent = [-1] * (counter+1)
        parent[0] = 0
        stack = [0]
        while stack:
            top = stack.pop()
            if top == counter:
                break
            for i in range(counter+1):
                if flo[top][i] and parent[i] == -1:
                    parent[i] = top
                    stack.append(i)
        if parent[counter] == -1:
            return 0
        # find min capacity along path
        ans = 10000
        pos = counter
        while pos != 0:
            ans = min(ans, flo[parent[pos]][pos])
            pos = parent[pos]
        # update capacities
        pos = counter
        while pos != 0:
            flo[parent[pos]][pos] -= ans
            flo[pos][parent[pos]] += ans
            pos = parent[pos]
        return ans

    total_flow = 0
    while True:
        f = get_path()
        if f == 0:
            break
        total_flow += f

    print(total_flow)

if __name__ == "__main__":
    solve()
